import React, { useEffect, useState } from 'react'
import MainNav from '../MainNav/MainNav'
import axios from 'axios';
import Artist from '../Manuth/Artist/Artist';

const URL = "http://localhost:5000/artists";

const fetchHandler = async () => {
  return await axios.get(URL).then((res) => res.data)
}

function Artists() {

  const [artists, setArtists] = useState();
  useEffect(()=>{
    fetchHandler().then((data) => setArtists(data.artists));
  },[])

  const{artist_id,artistName,genre,category,bookingPrice,summary,bio,image} = props.artist;

  return (
    
    <div>
      <MainNav></MainNav>
      <h1>Artist Details Display Page</h1>
      <div>
        {artists && artists.map((artist, i) =>(
          <div key = {i}>
            <Artist artist = {artist}></Artist>
          </div>
        ))}
      </div>

      <br></br>
      <h1>ID:{artist_id}</h1>
      <h1>Artist Name:{artistName}</h1>
      <h1>Genre:{genre}</h1>
      <h1>Catergory:{category}</h1>
      <h1>Booking Price:{bookingPrice}</h1>
      <h1>Summary:{summary}</h1>
      <h1>Bio:{bio}</h1>
      <h1>Image:{image}</h1>

    </div>
  )
}

export default Artists
